    css: "/* From Uiverse.io by Cksunandh  - Tags: form */\n.file-upload-container {\n  width: 50%;\n  max-width: 500px;\n}\n\n.file-upload {\n  position: relative;\n  border: 2px dashed #b8bcbf;\n  border-radius: 10px;\n  padding: 40px;\n  text-align: center;\n  background-color: rgb(255, 255, 255);\n  transition: background-color 0.3s ease-in-out;\n}\n\n.file-upload:hover {\n  background-color: #e2e6ea;\n}\n\n.file-input {\n  display: none;\n}\n\n.file-label {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  cursor: pointer;\n}\n\n.upload-icon {\n  font-size: 50px;\n  color: #007bff;\n  margin-bottom: 10px;\n}\n\n.file-upload p {\n  margin: 0;\n  font-size: 16px;\n  color: #6c757d;\n}\n\n.file-upload.dragover {\n  background-color: #007bff;\n  color: white;\n}",
