    css: "/* From Uiverse.io by Praashoo7 - Tags: neumorphism, login, form */\n.form {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  background-color: white;\n  padding: 2.5em;\n  border-radius: 25px;\n  transition: .4s ease-in-out;\n  box-shadow: rgba(0, 0, 0, 0.4) 1px 2px 2px;\n}\n\n.form:hover {\n  transform: translateX(-0.5em) translateY(-0.5em);\n  border: 1px solid #171717;\n  box-shadow: 10px 10px 0px #666666;\n}\n\n.heading {\n  color: black;\n  padding-bottom: 2em;\n  text-align: center;\n  font-weight: bold;\n}\n\n.input {\n  border-radius: 5px;\n  border: 1px solid whitesmoke;\n  background-color: whitesmoke;\n  outline: none;\n  padding: 0.7em;\n  transition: .4s ease-in-out;\n}\n\n.input:hover {\n  box-shadow: 6px 6px 0px #969696,\n             -3px -3px 10px #ffffff;\n}\n\n.input:focus {\n  background: #ffffff;\n  box-shadow: inset 2px 5px 10px rgba(0,0,0,0.3);\n}\n\n.form .btn {\n  margin-top: 2em;\n  align-self: center;\n  padding: 0.7em;\n  padding-left: 1em;\n  padding-right: 1em;\n  border-radius: 10px;\n  border: none;\n  color: black;\n  transition: .4s ease-in-out;\n  box-shadow: rgba(0, 0, 0, 0.4) 1px 1px 1px;\n}\n\n.form .btn:hover {\n  box-shadow: 6px 6px 0px #969696,\n             -3px -3px 10px #ffffff;\n  transform: translateX(-0.5em) translateY(-0.5em);\n}\n\n.form .btn:active {\n  transition: .2s;\n  transform: translateX(0em) translateY(0em);\n  box-shadow: none;\n}",
