    css: "/* From Uiverse.io by krlozCJ - Tags: neumorphism, login, form */\n.container {\n  width: 300px;\n  position: relative;\n  border-radius: 5px;\n  overflow: hidden;\n  box-shadow: 1.5px 1.5px 3px #0e0e0e, -1.5px -1.5px 3px rgb(95 94 94 / 25%), inset 0px 0px 0px #0e0e0e, inset 0px -0px 0px #5f5e5e;\n}\n\n.container .slider {\n  width: 200%;\n  position: relative;\n  transition: transform ease-out 0.3s;\n  display: flex;\n}\n\n#register_toggle {\n  display: none;\n}\n\n.container #register_toggle:checked + .slider {\n  transform: translateX(-50%);\n}\n\n.form {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n  gap: 30px;\n  padding: 1.5em 3em;\n  width: 50%;\n}\n\n.title {\n  text-align: center;\n  font-weight: 700;\n  font-size: 2em;\n}\n\nform .form_control {\n  width: 100%;\n  position: relative;\n  overflow: hidden;\n}\n\nform .form_control .label {\n  position: absolute;\n  top: 50%;\n  left: 10px;\n  transition: transform ease 0.2s;\n  transform: translate(0%, -50%);\n  font-size: 0.75em;\n  user-select: none;\n  pointer-events: none;\n  color: #b0b0b0;\n}\n\nform .form_control .input {\n  width: 100%;\n  background-color: transparent;\n  border: none;\n  outline: none;\n  color: #fff;\n  padding: 0.5rem;\n  font-size: 0.75rem;\n  border-radius: 5px;\n  transition: box-shadow ease 0.2s;\n  box-shadow: 0px 0px 0px #0e0e0e, 0px 0px 0px rgb(95 94 94 / 25%), inset 1.5px 1.5px 3px #0e0e0e, inset -1.5px -1.5px 3px #5f5e5e;\n}\n\nform .form_control .input:focus,\nform .form_control .input:valid {\n  box-shadow: 0px 0px 0px #0e0e0e, 0px 0px 0px rgb(95 94 94 / 25%), inset 3px 3px 4px #0e0e0e, inset -3px -3px 4px #5f5e5e;\n}\n\nform .form_control .input:focus + .label,\nform .form_control .input:valid + .label {\n  transform: translate(-150%, -50%);\n}\n\nform button {\n  width: 100%;\n  background-color: transparent;\n  border: none;\n  outline: none;\n  color: #fff;\n  padding: 0.5rem;\n  font-size: 0.75rem;\n  border-radius: 5px;\n  transition: box-shadow ease 0.1s;\n  box-shadow: 1.5px 1.5px 3px #0e0e0e, -1.5px -1.5px 3px rgb(95 94 94 / 25%), inset 0px 0px 0px #0e0e0e, inset 0px -0px 0px #5f5e5e;\n}\n\nform button:active {\n  box-shadow: 0px 0px 0px #0e0e0e, 0px 0px 0px rgb(95 94 94 / 25%), inset 3px 3px 4px #0e0e0e, inset -3px -3px 4px #5f5e5e;\n}\n\n.bottom_text {\n  font-size: 0.65em;\n}\n\n.bottom_text .swtich {\n  font-weight: 700;\n  cursor: pointer;\n}",
