    css: "/* From Uiverse.io by sahilxkhadka - Tags: facebook, form, login , loginform */\n.logo {\n  margin-bottom: 1rem;\n  font-size: 1.2rem;\n  text-align: center;\n  color: #1877f2;\n  font-weight: 700;\n}\n\nform {\n  display: flex;\n  flex-direction: column;\n  background: #fff;\n  padding: 1.5rem 1rem;\n  width: 300px;\n  border-radius: 0.5rem;\n  box-shadow: 0 2px 4px rgb(0 0 0 / 10%), 0 8px 16px rgb(0 0 0 / 10%);\n}\n\nform input {\n  outline: none;\n  padding: 0.4rem 0.5rem;\n  margin-bottom: 0.8rem;\n  font-size: 0.9rem;\n}\n\nform input:focus {\n  border: 1.8px solid #1877f2;\n}\n\nform .login {\n  outline: none;\n  border: none;\n  background: #1877f2;\n  padding: 0.8rem 1rem;\n  border-radius: 0.4rem;\n  font-size: 0.9rem;\n  color: #fff;\n}\n\nform .login:hover {\n  background: #0f71f1;\n  cursor: pointer;\n}\n\nform a {\n  text-decoration: none;\n  text-align: center;\n  font-size: 0.9rem;\n  padding-top: 0.8rem;\n  color: #1877f2;\n}\n\nform hr {\n  background: #f7f7f7;\n  margin: 0.5rem;\n}\n\nform .create-account {\n  outline: none;\n  border: none;\n  background: #06b909;\n  padding: 0.8rem 1rem;\n  border-radius: 0.5rem;\n  font-size: 0.9rem;\n  color: #fff;\n  width: 75%;\n  margin: 0 auto;\n}\n\nform .create-account:hover {\n  background: #03ad06;\n  cursor: pointer;\n}",
